// 1) Verify Meta's X-Hub-Signature-256 on the RAW body before trusting anything.
const crypto = require('crypto');
const cfg = $('Config').first().json;
const item = $('Webhook: WhatsApp inbound (Meta Cloud API)').first();
const headers = item.json.headers || {};
const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString() : JSON.stringify(item.json.body || {});
const expected = 'sha256=' + crypto.createHmac('sha256', cfg.app_secret).update(raw).digest('hex');
const given = String(headers['x-hub-signature-256'] || '');
const ok = given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
if (!ok) return [{ json: { kind: 'forged', reason: 'X-Hub-Signature-256 mismatch', source_ip: headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown', base: cfg.base, bytes: raw.length } }];
const body = item.json.body || JSON.parse(raw);

// 2) Conversation memory + idempotency live in workflow static data (swap for Redis/Postgres at scale).
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {}; sd.conv = sd.conv || {};
const now = Date.now();
for (const [k, t] of Object.entries(sd.seen)) if (now - t > 7 * 864e5) delete sd.seen[k];

// 3) Parse every change in the payload: delivery statuses are acknowledged, messages become events.
const out = [];
for (const e of body.entry || []) for (const ch of e.changes || []) {
  const v = ch.value || {};
  if (v.statuses?.length) { out.push({ kind: 'status', statuses: v.statuses.map(s => s.status) }); continue; }
  const nameOf = {}; for (const c of v.contacts || []) nameOf[c.wa_id] = c.profile?.name;
  for (const m of v.messages || []) {
    if (sd.seen[m.id]) { out.push({ kind: 'duplicate', wamid: m.id, wa_id: m.from }); continue; }   // Meta retries deliveries
    sd.seen[m.id] = now;
    const text = m.type === 'text' ? (m.text?.body || '')
      : m.type === 'button' ? (m.button?.text || '')
      : m.type === 'interactive' ? (m.interactive?.button_reply?.title || m.interactive?.list_reply?.title || '')
      : `[${m.type} message]`;
    const wa = m.from;
    const conv = sd.conv[wa] || (sd.conv[wa] = { wa_id: wa, name: '', turns: [], stage: 'new', handoff: false, opted_out: false, created_at: now });
    conv.name = nameOf[wa] || conv.name;
    conv.last_inbound_ts = (Number(m.timestamp) * 1000) || now;
    conv.turns.push({ role: 'user', text, ts: conv.last_inbound_ts }); conv.turns = conv.turns.slice(-10);
    let kind = 'message';
    if (/^\s*(stop|unsubscribe|band karo|cancel)\s*$/i.test(text)) { kind = 'optout'; conv.opted_out = true; conv.stage = 'opted_out'; }
    else if (conv.opted_out) { conv.opted_out = false; conv.stage = 're-engaged'; }          // they wrote again → re-engaged
    else if (conv.handoff) kind = 'handoff_active';                                           // a human owns this chat now
    out.push({ kind, wamid: m.id, wa_id: wa, name: conv.name, text, type: m.type, phone_number_id: v.metadata?.phone_number_id || cfg.phone_number_id,
               history: conv.turns.slice(0, -1).slice(-6), stage: conv.stage, base: cfg.base, wa_token: cfg.wa_token, business: JSON.parse(cfg.business_profile), sales_channel: cfg.sales_channel });
  }
}
if (!out.length) out.push({ kind: 'status', statuses: [] });
return out.map(j => ({ json: j }));

const ev = $('Verify signature, parse, dedupe, remember').first().json;
const ai = $json.output;
const sd = $getWorkflowStaticData('global');
const conv = sd.conv[ev.wa_id];
conv.turns.push({ role: 'assistant', text: ai.reply, ts: Date.now() }); conv.turns = conv.turns.slice(-10);
conv.stage = ai.needs_human ? 'handoff' : (ai.booking_requested ? 'booking' : 'awaiting_reply');
conv.last_outbound_ts = Date.now();
conv.lead_score = ai.lead_score; conv.language = ai.language;
conv.collected = { ...(conv.collected || {}), ...(ai.collected || {}) };
conv.followup_sent = false;
if (ai.needs_human) conv.handoff = true;
const route = ai.needs_human ? 'human' : (ai.booking_requested ? 'booking' : 'reply');
return [{ json: { ...ev, ai, route, collected: conv.collected, usage: $json.usage } }];

// Nudge quiet conversations. Inside Meta's 24-hour customer-service window a free-form text is allowed;
// outside it only an approved template may be sent. Opted-out, handed-off and already-nudged chats are skipped.
const cfg = $('Config (follow-ups)').first().json;
const force = !!($json.query?.force || $json.body?.force);
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const out = [];
for (const c of Object.values(sd.conv || {})) {
  const quietMin = (now - Math.max(c.last_inbound_ts || 0, c.last_outbound_ts || 0)) / 60000;
  const hours = (now - (c.last_inbound_ts || 0)) / 36e5;
  let skip = null;
  if (c.opted_out) skip = 'opted_out';
  else if (c.handoff) skip = 'human_owns_chat';
  else if (c.followup_sent) skip = 'already_nudged';
  else if (c.stage === 'booked') skip = 'booked';
  else if (!force && quietMin < Number(cfg.nudge_after_min)) skip = 'not_quiet_yet';
  if (skip) { out.push({ json: { wa_id: c.wa_id, name: c.name, action: 'skip', reason: skip } }); continue; }
  const inside = hours < 24;
  c.followup_sent = true; c.followup_ts = now;
  out.push({ json: { wa_id: c.wa_id, name: c.name, action: inside ? 'freeform_nudge' : 'template', inside_window: inside, hours_since_inbound: +hours.toFixed(1),
                     language: c.language || 'en', base: cfg.base, wa_token: cfg.wa_token, phone_number_id: cfg.phone_number_id, template: cfg.followup_template } });
}
return out.length ? out : [{ json: { action: 'skip', reason: 'no_conversations' } }];

const rows = $('Find quiet conversations').all().map(i => i.json);
const sent = rows.filter(r => r.action !== 'skip');
return [{ json: { ran_at: new Date().toISOString(), conversations: rows.length, nudged_freeform: sent.filter(r => r.action === 'freeform_nudge').length,
  nudged_template: sent.filter(r => r.action === 'template').length, skipped: rows.filter(r => r.action === 'skip').reduce((a, r) => { a[r.reason] = (a[r.reason] || 0) + 1; return a; }, {}),
  detail: rows.map(r => ({ wa_id: r.wa_id, action: r.action, reason: r.reason, hours_since_inbound: r.hours_since_inbound })) } }];
